router = APIRouter(prefix="/api/room", tags=["房间管理"])


class CreateRoomRequest(BaseModel):
 """创建房间请求"""
 user_id: str
 domain_enum: int = 1 # 1: 公共房间, 2: 私有房间


class JoinRoomRequest(BaseModel):
 """加入房间请求"""
 user_id: str
 room_code: str


class RoomInfoResponse(BaseModel):
 """房间信息响应"""
 room_code: str
 domain: str
 creator: str
 members: List[str]
 online: List[str]
 created_at: float


class PublicRoomListResponse(BaseModel):
 """公共房间列表响应"""
 rooms: List[RoomInfoResponse]


@router.post("/create", response_model=dict)
async def create_room_api(request: CreateRoomRequest):
 """
 创建房间

 Args:
 request: 创建房间请求参数

 Returns:
 {"room_code": "房间码", "message": "创建成功"}
 """
 try:
 room_code = create_room(request.user_id, domain_enum=request.domain_enum)
 return {
 "room_code": room_code,
 "message": "房间创建成功"
 }
 except Exception as e:
 raise HTTPException(status_code=500, detail=str(e))


@router.post("/join", response_model=dict)
async def join_room_api(request: JoinRoomRequest):
 """
 加入房间

 Args:
 request: 加入房间请求参数

 Returns:
 {"message": "加入成功", "room_info": 房间信息}
 """
 try:
 join_room(request.user_id, request.room_code)
 room_info = get_room_info(request.room_code)
 return {
 "message": "加入房间成功",
 "room_info": {
 "room_code": request.room_code,
 "domain": room_info["domain"],
 "creator": room_info["creator"],
 "members_count": len(room_info["members"]),
 "online_count": len(room_info["online"]),
 "created_at": room_info["created_at"]
 }
 }
 except KeyError:
 raise HTTPException(status_code=404, detail="房间不存在")
 except Exception as e:
 raise HTTPException(status_code=500, detail=str(e))


@router.post("/leave", response_model=dict)
async def leave_room_api(request: JoinRoomRequest):
 """
 离开房间

 Args:
 request: 离开房间请求参数

 Returns:
 {"message": "离开成功"}
 """
 try:
 level_room(request.user_id, request.room_code)
 return {"message": "离开房间成功"}
 except KeyError:
 raise HTTPException(status_code=404, detail="房间不存在")
 except Exception as e:
 raise HTTPException(status_code=500, detail=str(e))


@router.get("/info/{room_code}", response_model=RoomInfoResponse)
async def get_room_info_api(room_code: str):
 """
 获取房间详细信息

 Args:
 room_code: 房间码

 Returns:
 房间详细信息
 """
 try:
 room_info = get_room_info(room_code)
 return RoomInfoResponse(
 room_code=room_code,
 domain=room_info["domain"],
 creator=room_info["creator"],
 members=list(room_info["members"]),
 online=list(room_info["online"]),
 created_at=room_info["created_at"]
 )
 except KeyError:
 raise HTTPException(status_code=404, detail="房间不存在")


@router.get("/public/list", response_model=PublicRoomListResponse)
async def get_public_room_list_api():
 """
 获取公共房间列表

