 InvalidDomainError, RoomAlreadyExistsError
)
from log.logger import logger, log_api_request, log_exception

router = APIRouter(prefix="/api/room", tags=["房间管理"])


class CreateRoomRequest(BaseModel):
 """创建房间请求"""
 user_id: str
 domain_enum: int = 1 # 1: 公共房间, 2: 私有房间


class JoinRoomRequest(BaseModel):
 """加入房间请求"""
 user_id: str
 room_code: str


class RoomInfoResponse(BaseModel):
 """房间信息响应"""
 room_code: str
 domain: str
 creator: str
 members: List[str]
 online: List[str]
 created_at: float


class PublicRoomListResponse(BaseModel):
 """公共房间列表响应"""
 rooms: List[RoomInfoResponse]


class ErrorResponse(BaseModel):
 """错误响应模型"""
 error_code: str
 message: str
 detail: Optional[str] = None


# 自定义异常处理器
def handle_service_exception(e: Exception) -> HTTPException:
 """处理服务层异常并转换为HTTP异常"""
 if isinstance(e, RoomNotFoundError):
 return HTTPException(status_code=404, detail={
 "error_code": e.error_code,
 "message": e.message
 })
 elif isinstance(e, (InvalidDomainError, UserNotInRoomError)):
 return HTTPException(status_code=400, detail={
 "error_code": e.error_code,
 "message": e.message
 })
 elif isinstance(e, RoomAlreadyExistsError):
 return HTTPException(status_code=409, detail={
 "error_code": e.error_code,
 "message": e.message
 })
 elif isinstance(e, RoomServiceError):
 return HTTPException(status_code=500, detail={
 "error_code": e.error_code,
 "message": e.message
 })
 else:
 return HTTPException(status_code=500, detail={
 "error_code": "INTERNAL_ERROR",
 "message": "服务器内部错误",
 "detail": str(e)
 })


